#!/usr/bin/env node
/**
 * Snapshots git HEAD + recent commit subjects into a TS module the
 * shared package re-exports. Both the server (for /build-info) and the
 * client (to compare its bundled SHA against the live server's SHA on
 * reconnect) read from the same constant.
 *
 * Runs from package.json `prepare`/`predev`/`prebuild`/`pretypecheck`
 * hooks so the generated file is always present and reasonably fresh.
 * If git is unavailable (e.g., a tarball install with no .git), falls
 * back to a `dev` placeholder — clients in that mode never trigger
 * the update modal because every server reports `dev`.
 */
import { execFileSync } from "node:child_process";
import { writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

// execFileSync (no shell) so format placeholders like `%s` and the
// `|` separator don't get interpreted by bash.
function git(...args) {
  try {
    return execFileSync("git", args, { cwd: root, encoding: "utf8" }).trim();
  } catch {
    return "";
  }
}

const sha = git("rev-parse", "--short", "HEAD") || "dev";
// %ct is committer date in unix seconds; convert to ms for JS Date.
const commitTimeSec = Number(git("log", "-1", "--pretty=format:%ct") || 0);
const time = commitTimeSec > 0 ? commitTimeSec * 1000 : Date.now();

// Last 12 commits, no merges. Each line: `<short-sha>|<subject>`.
// Pipe is safe because subjects don't contain it.
const log = git("log", "-12", "--no-merges", "--pretty=format:%h|%s");
const notes = log
  ? log
      .split("\n")
      .map((line) => {
        const idx = line.indexOf("|");
        if (idx < 0) return null;
        return {
          sha: line.slice(0, idx),
          subject: line.slice(idx + 1),
        };
      })
      .filter((n) => n !== null)
  : [];

const payload = { sha, time, notes };

const target = resolve(root, "packages/shared/src/build-info.generated.ts");
mkdirSync(dirname(target), { recursive: true });
const body = `// Auto-generated by scripts/gen-build-info.mjs. Do not edit.
import type { BuildInfo } from "./build-info.js";
export const BUILD_INFO: BuildInfo = ${JSON.stringify(payload, null, 2)};
`;
writeFileSync(target, body);
console.log(`[gen-build-info] sha=${sha} notes=${notes.length} → ${target}`);
